"use strict";

const http = require("http");

function codeOf(error) {
  return error && (error.autojs6Code || error.code || error.name) || "";
}

function requestWithSignal(url, signal) {
  return new Promise((resolve) => {
    const req = http.request(url, { signal, timeout: 1000 }, (res) => {
      res.resume();
      res.on("end", () => resolve("allowed"));
    });
    req.on("error", (error) => resolve(codeOf(error)));
    req.end();
  });
}

exports.probe = async function probe(ctx) {
  const beforePre = ctx.requestCount();
  const preController = new AbortController();
  preController.abort();
  const preCode = await requestWithSignal("http://example.invalid/abort-pre", preController.signal);
  const afterPre = ctx.requestCount();

  const duringController = new AbortController();
  const during = requestWithSignal("http://example.invalid/abort-during", duringController.signal);
  setImmediate(() => duringController.abort());
  const duringCode = await during;

  return [
    "httpnpm.abort-signal=" + preCode,
    duringCode,
    "pre=" + (afterPre - beforePre),
  ].join("|");
};
